// GENERATED by `npm run sync:shared` from frontend/src/shared. Do not edit: change the
// frontend file and run the script again.
/** Small text helpers shared across features. */

/**
 * Crude similarity score in 0..1, used to suggest near-duplicate company names
 * while the user types a new one (spec 6.4: avoid `Google` and `Google LLC`).
 *
 * This is a UX nudge only. The authoritative duplicate check belongs to the
 * backend, which can compare normalised names and website hostnames across the
 * whole database rather than the page of results the client happens to hold.
 */
export function nameSimilarity(a: string, b: string): number {
  const left = normalizeCompanyName(a);
  const right = normalizeCompanyName(b);
  if (left.length === 0 || right.length === 0) return 0;
  if (left === right) return 1;
  if (left.startsWith(right) || right.startsWith(left)) return 0.9;
  if (left.includes(right) || right.includes(left)) return 0.75;

  const leftTokens = new Set(left.split(' '));
  const rightTokens = new Set(right.split(' '));
  let shared = 0;
  for (const token of leftTokens) {
    if (rightTokens.has(token)) shared += 1;
  }
  const union = new Set([...leftTokens, ...rightTokens]).size;
  return union === 0 ? 0 : shared / union;
}

/** Drop legal suffixes and punctuation so `Acme, Inc.` matches `Acme`. */
export function normalizeCompanyName(name: string): string {
  return name
    .toLowerCase()
    .replace(/[.,]/g, ' ')
    .replace(/\b(inc|llc|ltd|limited|corp|corporation|co|company|plc|gmbh)\b/g, ' ')
    .replace(/[^a-z0-9& ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Name autocomplete for "Add this company": the companies whose name best
 * matches what has been typed so far, best first.
 *
 * 1. the name starts with it ("a" -> Amazon, Apple),
 * 2. a later word starts with it ("ridge" -> Orchid Ridge Bank),
 * 3. the name contains it (2+ characters),
 * 4. most of the same words (3+ characters, "orchid bank" -> Orchid Ridge Bank).
 *
 * Ties are A to Z. Unlike the main company search, location and focus never count.
 */
export function suggestCompanyNames<T extends { name: string }>(
  query: string,
  companies: readonly T[],
  limit: number,
): T[] {
  const typed = normalizeCompanyName(query);
  if (!typed) return [];

  function tier(name: string): number | null {
    const normalized = normalizeCompanyName(name);
    if (normalized.startsWith(typed)) return 0;
    if (normalized.split(' ').some((word) => word.startsWith(typed))) return 1;
    if (typed.length >= 2 && normalized.includes(typed)) return 2;
    if (typed.length >= 3 && nameSimilarity(typed, normalized) >= 0.5) return 3;
    return null;
  }

  return companies
    .map((company) => ({ company, tier: tier(company.name) }))
    .filter((hit): hit is { company: T; tier: number } => hit.tier !== null)
    .sort((a, b) => a.tier - b.tier || a.company.name.localeCompare(b.company.name))
    .slice(0, limit)
    .map((hit) => hit.company);
}

/** Join items into `a, b and c`. */
export function joinWithAnd(items: readonly string[]): string {
  if (items.length === 0) return '';
  if (items.length === 1) return items[0] ?? '';
  const head = items.slice(0, -1).join(', ');
  const tail = items[items.length - 1] ?? '';
  return `${head} and ${tail}`;
}

/** Generate a random identifier. Used for client-side idempotency keys. */
export function createClientId(prefix = 'c'): string {
  const globalCrypto = globalThis.crypto;
  if (globalCrypto && 'randomUUID' in globalCrypto) {
    return `${prefix}_${globalCrypto.randomUUID()}`;
  }
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
}
